const axios = require('axios');

async function run() {
  // Get variables from Botpress
  const topic = bp.dialogEngine.getVariable('topic') || 'NLP';
  const level = bp.dialogEngine.getVariable('UserLevel') || 'Beginner';
  const template = 'Full Study Guide';

  try {
    // Call Hugging Face Space API
    const response = await axios.post(
      'https://mbalimadlala-ai-learnmate-generator.hf.space/run/predict',
      { data: [topic, level, template] }
    );

    // Extract generated content
    const generatedContent = response.data.data[0];
    bp.dialogEngine.setVariable('StudyGuide', generatedContent);
  } catch (error) {
    bp.logger.error('Hugging Face API Error:', error.message);
    bp.dialogEngine.setVariable('StudyGuide', 'Sorry, could not generate content.');
  }
}

return run();

